-- Fixed PR14c PG17.11 exported definitions. No caller-supplied SQL.
-- Temporary DDL is NOT read-only. Execute only on a root-assigned disposable verifier.
\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ;
SET LOCAL statement_timeout = '15s';
SET LOCAL lock_timeout = '1s';
SET LOCAL search_path = pg_catalog;
SET LOCAL timezone = 'UTC';
DO $pr14c_guard$ BEGIN
 IF current_setting('server_version_num')::int <> 170011 OR current_database()<>'nomorevibe_test' OR current_user<>'nomorevibe' OR pg_is_in_recovery() THEN RAISE EXCEPTION 'pr14c_verifier_identity'; END IF;
 IF pg_my_temp_schema()<>0 OR EXISTS(SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND backend_type='client backend') THEN RAISE EXCEPTION 'pr14c_verifier_not_exclusive'; END IF;
 IF EXISTS(SELECT 1 FROM pg_collation c JOIN pg_namespace n ON n.oid=c.collnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema') THEN RAISE EXCEPTION 'pr14c_user_collation_unknown'; END IF;
 -- Fixed trusted function: public.invalidate_product_search_profile()
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='public.invalidate_product_search_profile()'::regprocedure AND pg_get_functiondef(p.oid)='CREATE OR REPLACE FUNCTION public.invalidate_product_search_profile()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE product_search_profiles
    SET needs_refresh = true, source_revision = source_revision + 1,
        attempts = 0, error_code = null, retry_at = null
    WHERE product_id = NEW.id;
  RETURN NEW;
END;
$function$
' AND pg_get_userbyid(p.proowner)='nomorevibe' AND p.proconfig IS NULL AND NOT p.prosecdef AND NOT p.proretset) THEN RAISE EXCEPTION 'pr14c_function_context_unknown'; END IF;
 -- Fixed trusted function: public.search_profile_description(text, text)
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='public.search_profile_description(text, text)'::regprocedure AND pg_get_functiondef(p.oid)='CREATE OR REPLACE FUNCTION public.search_profile_description(value text, tagline text)
 RETURNS bytea
 LANGUAGE sql
 IMMUTABLE STRICT
AS $function$
  -- ECMAScript trim whitespace, matching profileEvidence''s optional description.
  SELECT CASE WHEN btrim(value, ws) = btrim(tagline, ws) THEN NULL ELSE search_profile_prefix(value, 600) END
  FROM (SELECT chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(160)||chr(5760)||
    chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||
    chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279) AS ws) trimmed;
$function$
' AND pg_get_userbyid(p.proowner)='nomorevibe' AND p.proconfig IS NULL AND NOT p.prosecdef AND NOT p.proretset) THEN RAISE EXCEPTION 'pr14c_function_context_unknown'; END IF;
 -- Fixed trusted function: public.search_profile_prefix(text, integer)
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='public.search_profile_prefix(text, integer)'::regprocedure AND pg_get_functiondef(p.oid)='CREATE OR REPLACE FUNCTION public.search_profile_prefix(value text, units integer)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE used integer := 0; i integer; code integer; width integer;
BEGIN
  FOR i IN 1..least(length(value), units) LOOP
    code := ascii(substr(value, i, 1));
    width := CASE WHEN code > 65535 THEN 2 ELSE 1 END;
    IF used + width > units THEN
      RETURN decode(''01'', ''hex'') || convert_to(substr(value, 1, i - 1), ''UTF8'') || decode(lpad(to_hex(55296 + (code - 65536) / 1024), 4, ''0''), ''hex'');
    END IF;
    used := used + width;
    IF used = units THEN RETURN decode(''00'', ''hex'') || convert_to(substr(value, 1, i), ''UTF8''); END IF;
  END LOOP;
  RETURN decode(''00'', ''hex'') || convert_to(value, ''UTF8'');
END;
$function$
' AND pg_get_userbyid(p.proowner)='nomorevibe' AND p.proconfig IS NULL AND NOT p.prosecdef AND NOT p.proretset) THEN RAISE EXCEPTION 'pr14c_function_context_unknown'; END IF;
END $pr14c_guard$;
SELECT jsonb_build_object('frame','identity','value',jsonb_build_object('version',current_setting('server_version_num')::int,'database',current_database(),'user',current_user,'backendPid',pg_backend_pid(),'transactionId',pg_current_xact_id()::text));
