SELECT jsonb_build_object('frame','context','value',jsonb_build_object(
 'version',current_setting('server_version_num')::int,
 'database',(SELECT jsonb_build_object('encoding',pg_encoding_to_char(d.encoding),'provider',d.datlocprovider,'locale',d.datlocale,'collate',d.datcollate,'ctype',d.datctype,'icuRules',d.daticurules,'version',d.datcollversion,'actualVersion',pg_database_collation_actual_version(d.oid)) FROM pg_database d WHERE d.datname=current_database()),
 'types',(SELECT jsonb_agg(jsonb_build_object('oid',t.oid::bigint,'namespace',n.nspname,'name',t.typname,'kind',t.typtype,'base',t.typbasetype::bigint,'element',t.typelem::bigint,'length',t.typlen,'byValue',t.typbyval) ORDER BY t.oid) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='pg_catalog' AND t.typtype='b'),
 'operators',(SELECT jsonb_agg(jsonb_build_object('oid',o.oid::bigint,'namespace',n.nspname,'name',o.oprname,'left',o.oprleft::bigint,'right',o.oprright::bigint,'result',o.oprresult::bigint,'function',o.oprcode::oid::bigint) ORDER BY o.oid) FROM pg_operator o JOIN pg_namespace n ON n.oid=o.oprnamespace WHERE n.nspname='pg_catalog'),
 'functions',(SELECT jsonb_agg(jsonb_build_object('oid',p.oid::bigint,'namespace',n.nspname,'name',p.proname,'args',to_jsonb(p.proargtypes::oid[]::bigint[]),'result',p.prorettype::bigint,'volatility',p.provolatile,'definition',CASE WHEN n.nspname='pg_catalog' THEN jsonb_build_object('src',p.prosrc,'bin',p.probin,'body',p.prosqlbody::text)::text ELSE pg_get_functiondef(p.oid) END,'config',p.proconfig,'owner',pg_get_userbyid(p.proowner),'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'strict',p.proisstrict,'returnsSet',p.proretset,'securityDefiner',p.prosecdef,'parallel',p.proparallel,'leakproof',p.proleakproof) ORDER BY p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND (n.nspname='pg_catalog' OR (n.nspname='public' AND p.proname IN ('search_profile_description','search_profile_prefix','invalidate_product_search_profile')))),
 'casts',(SELECT jsonb_agg(jsonb_build_object('source',castsource::bigint,'target',casttarget::bigint,'method',castmethod,'context',castcontext,'function',castfunc::oid::bigint) ORDER BY castsource,casttarget) FROM pg_cast),
 'collations',(SELECT jsonb_agg(jsonb_build_object('oid',c.oid::bigint,'namespace',n.nspname,'name',c.collname,'provider',c.collprovider,'deterministic',c.collisdeterministic,'encoding',c.collencoding,'collate',c.collcollate,'ctype',c.collctype,'locale',c.colllocale,'icuRules',c.collicurules,'version',CASE WHEN c.collprovider='d' THEN d.datcollversion ELSE c.collversion END,'actualVersion',CASE WHEN c.collprovider='d' THEN pg_database_collation_actual_version(d.oid) ELSE pg_collation_actual_version(c.oid) END) ORDER BY c.oid) FROM pg_collation c JOIN pg_namespace n ON n.oid=c.collnamespace CROSS JOIN pg_database d WHERE n.nspname='pg_catalog' AND c.collname IN ('default','C','POSIX') AND d.datname=current_database())
));
